 s+=g('pop',tk(c,'a4'),CL_arrow(310,170,310,114,GRN,6)+`<rect x="216" y="60" width="188" height="52" rx="6" fill="none" stroke="${GRN}" stroke-width="5"/>`+CL_T(310,500,'aim for the target band',{fs:26,fw:800,a:'middle',fill:GRN}));
