 let s=stack(20,'outdoors: 35 °C air','fins 160 °C',BLU)+stack(330,'closed shed: 55 °C air','fins 180 °C',RED);
 s+=g('pop',tk(c,'a1'),CL_L(226,112,226,290,GRN,4)+CL_L(218,112,234,112,GRN,4)+CL_L(218,290,234,290,GRN,4)+CL_T(246,206,'ΔT',{fs:22,fw:800,fill:GRN})+CL_L(536,112,536,290,GRN,4)+CL_L(528,112,544,112,GRN,4)+CL_L(528,290,544,290,GRN,4)+CL_T(556,206,'ΔT',{fs:22,fw:800,fill:GRN})+CL_T(310,410,'same Q, h, A: same ΔT = 125 K',{fs:24,fw:800,a:'middle',fill:GRN}));
 s+=g('pop',tk(c,'a2'),CL_arrow(310,350,370,350,ORG,5)+CL_T(310,450,'160 − 35 = 180 − 55 = 125 K',{fs:22,fw:700,a:'middle',fill:CL_GREY}));
 s+=g('pop',tk(c,'a3'),CL_arrow(560,468,560,380,CL_WATER,5)+CL_T(610,496,'duct outside air in',{fs:22,fw:800,a:'end',fill:CL_WATER}));
